<?php
namespace App\Commands\Chat; use App\Commands\SafeBaseCommand; use App\Commands\Support\SubsCommandTrait;
class Repair extends SafeBaseCommand { use SubsCommandTrait; protected $group='Chat'; protected $name='chat:repair'; protected $description='Chat repairs'; protected $options=['--json'=>'JSON','--dry-run'=>'Dry']; public function run(array $params){$this->parseParams($params);$dry=$this->optBool('dry-run');$actions=[]; if(!is_dir(ROOTPATH.'chat/runtime')){if(!$dry){mkdir(ROOTPATH.'chat/runtime',0775,true);} $actions[]='created chat/runtime';} $report=['status'=>'ok','actions'=>$actions,'dry_run'=>$dry];$report['report']=$this->writeDoc('repairs','chat-repair-'.date('Y-m-d').'.md',"# Chat Repair\n\n- ".implode("\n- ",$actions?:['No changes needed'])."\n");$this->emit($report,$this->optBool('json'));return EXIT_SUCCESS;}}
